window.kbPageData["views/entry/k-c7384adfdc90f983"] = {"key":"entry/k-c7384adfdc90f983","state":{"route":"entry/k-c7384adfdc90f983"},"node":{"id":"k-c7384adfdc90f983","mode":"k","title":"圆柱与圆锥的体积公式","type":"原理与机制","domain":"数学","reading":"","intro":"","priority":100,"aliases":[],"qs":["国考 2023 行政执法 行测#70"],"current":false,"candidates":true,"sources":[],"basisGroup":"","authority":null,"sourceOnly":false,"reviewSet":"单次条目","independentCount":1,"repeatPositions":0,"directorySummary":"圆柱的体积为 πr²h，圆锥的体积为 πr²h/3。r 是底面半径，h 是高。","review":{"definition":"圆柱的体积为 πr²h，圆锥的体积为 πr²h/3。r 是底面半径，h 是高。","explanation":"底面半径加倍，底面积变为原来的 4 倍。第 70 题中，设两零件的共同高度为 h，则圆柱 A 的底面半径为 h，圆锥 B 的底面半径为 2h。代入公式得 A 的体积为 πh³，B 的体积为 4πh³/3，因此 B 的体积是 A 的 4/3 倍。","references":[],"evidence":"A的底面半径和高相同，B的底面半径是高的2倍，两个零件的高相同","disposition":"独立词条","basis":"据原题和解析编释。"}},"questions":{"国考 2023 行政执法 行测#70":{"paper":"国考 2023 行政执法 行测","n":70,"mod":"数量关系","src":["857378cf496f27296500.pdf",12],"asrc":["d23139fe5a0fb3115135.pdf",22],"card":"e4d9867587c4ddd73bc90403","links":[{"id":"k-c7384adfdc90f983","role":"解题依据","why":"圆柱体积等于底面积乘以高，圆锥体积等于底面积乘以高再除以三，可据此求两个零件的体积比。"}]}},"terms":{},"references":{},"topics":[],"units":{"k-c7384adfdc90f983":[["国考 2023 行政执法 行测#70"]]}};
